// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    function setUp() public { c = new PuttyV2("", 0, address(this)); }
    function testFuzz_property(address actor, address to, uint256 id) public {
        vm.assume(actor != address(0));
        vm.assume(to != address(0));

        // Rule: a transferFrom whose `from` does not own the token must revert.
        // No token can ever be minted via the external surface, so for every id
        // nobody owns it and actor does not own id; the call must revert in P.
        vm.prank(actor);
        try c.transferFrom(actor, to, id) {
            assertTrue(false, "transfer of non-owned token must revert");
        } catch {
            assertTrue(true);
        }
    }
}
